INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-wida-listening-364ad44d4f4e','WIDA','listening','mcq',1,'Sam says: "I''m hungry. I want an apple and a glass of milk."','What does Sam want?',NULL,'["An apple and milk","Bread and juice","Pizza","Water only"]',0,'Listen for the key detail.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-wida-listening-2628d200af60','WIDA','listening','mcq',2,'Announcement: "The school library will close early today at two o''clock because of a meeting. Please return your books before then."','Why will the library close early?',NULL,'["It is a holiday","There is a meeting","The books are missing","It is raining"]',1,'Listen for the key detail.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-wida-listening-cf881ea0ed7b','WIDA','listening','mcq',2,'Lena tells her friend: "I couldn''t come to practice yesterday because my little brother was sick, so I stayed home with him."','Why did Lena miss practice?',NULL,'["She was tired","She forgot","Her brother was sick","She had a test"]',2,'Listen for the key detail.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-wida-listening-68fbb825df71','WIDA','listening','mcq',3,'The science teacher explains: "Plants make their own food using sunlight, water, and air. This process is called photosynthesis."','What is photosynthesis?',NULL,'["A way plants make food","A kind of weather","A type of soil","A way animals sleep"]',0,'Listen for the key detail.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-wida-listening-59409333a2cf','WIDA','listening','mcq',3,'Coach: "We''ll meet at the north gate, not the main entrance. The bus leaves at eight, so please don''t be late."','Where will the students meet?',NULL,'["At the main entrance","At the north gate","On the bus","In the gym"]',1,'Listen for the key detail.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-wida-listening-9981ac1dfdce','WIDA','listening','mcq',3,'A guide says: "Please stay with the group, and do not touch the exhibits. If you have a question, raise your hand."','What should visitors do if they have a question?',NULL,'["Touch the exhibit","Leave the group","Raise their hand","Wait outside"]',2,'Listen for the key detail.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-wida-listening-a9553eccdd04','WIDA','listening','mcq',4,'Radio: "Tomorrow will start cloudy, but by afternoon the clouds should clear and the temperature will rise to twenty-five degrees."','What will the weather be like tomorrow afternoon?',NULL,'["Rainy and cold","Clear and warmer","Cloudy all day","Snowy"]',1,'Listen for the key detail.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-wida-listening-92216ca43da6','WIDA','listening','mcq',4,'Teacher: "Although the experiment failed, we learned that the metal expands when heated, which is useful information."','What did the class learn?',NULL,'["The experiment was perfect","Metal expands when heated","Metal melts at once","Heat is dangerous"]',1,'Listen for the key detail.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-wida-listening-abcc7e888a68','WIDA','listening','mcq',5,'Speaker: "Contrary to popular belief, goldfish can remember things for months, not seconds, which is why they can be trained to recognize feeding times."','What is the speaker''s main point?',NULL,'["Goldfish have poor memories","Goldfish can remember for months","Goldfish dislike feeding","Goldfish cannot be trained"]',1,'Listen for the key detail.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-wida-reading-b200855c0718','WIDA','reading','mcq',1,'Tom has a red ball. He plays with it at the park every day after school.','Where does Tom play with his ball?',NULL,'["At school","At the park","At home","At the beach"]',1,'Find the answer in the text.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-wida-reading-2bfed77a7ccd','WIDA','reading','mcq',2,'Rosa planted seeds in a small pot. She watered them every morning. After two weeks, tiny green leaves appeared.','What happened after two weeks?',NULL,'["The pot broke","Green leaves appeared","Rosa stopped watering","The seeds disappeared"]',1,'Find the answer in the text.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-wida-reading-fb2405f8ef42','WIDA','reading','mcq',2,'The class went to the zoo. They saw lions, monkeys, and a very tall giraffe. Everyone liked the monkeys best.','Which animal did everyone like best?',NULL,'["Lions","Giraffe","Monkeys","Elephants"]',2,'Find the answer in the text.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-wida-reading-4461fd4f2253','WIDA','reading','mcq',3,'Recycling means turning old things into new things. When we recycle paper, fewer trees are cut down, and less energy is used.','What is one benefit of recycling paper?',NULL,'["It makes more trash","Fewer trees are cut down","It costs more energy","It makes paper heavier"]',1,'Find the answer in the text.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-wida-reading-8cb68b9a5fff','WIDA','reading','mcq',3,'Because the river flooded last spring, the villagers built a wall of stones along its bank. Since then, the houses have stayed dry.','Why did the villagers build the wall?',NULL,'["To make a road","To stop the river flooding their homes","To catch fish","To start a market"]',1,'Find the answer in the text.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-wida-reading-8992850ce62f','WIDA','reading','mcq',4,'Volcanoes form where hot melted rock, called magma, rises through cracks in the Earth''s crust. When pressure builds up, the magma can erupt as lava.','What causes a volcano to erupt?',NULL,'["Heavy rain","Pressure from rising magma","Strong wind","Ocean waves"]',1,'Find the answer in the text.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-wida-reading-e9519e668b6a','WIDA','reading','mcq',4,'The word "transparent" means that light can pass through something so you can see clearly. Glass windows are usually transparent.','Which object is most likely transparent?',NULL,'["A wooden door","A glass window","A brick wall","A metal box"]',1,'Find the answer in the text.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-wida-reading-892013d9acd8','WIDA','reading','mcq',5,'Although the festival was small when it began, word of mouth gradually drew visitors from neighbouring towns, and within a decade it had become the region''s most anticipated event.','What can be inferred about the festival?',NULL,'["It stopped after ten years","It grew because people told others","It was always large","It only had local visitors"]',1,'Find the answer in the text.',1,0);
