INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-isee-reading-59f899a7c302','ISEE','reading','mcq',3,'In many coastal cities, rising sea levels are forcing planners to rethink where people can safely live. Some propose walls and pumps to hold the water back, while others argue that it is wiser to move neighborhoods inland and restore marshes that naturally absorb floods. Each approach is costly, but supporters of the second note that it can also create parks and wildlife habitat.','The passage is primarily concerned with',NULL,'["the cost of building walls","different responses to rising sea levels","the history of coastal cities","how marshes support wildlife"]',1,'Compares responses.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-isee-reading-dc1f638a78c1','ISEE','reading','mcq',4,'In many coastal cities, rising sea levels are forcing planners to rethink where people can safely live. Some propose walls and pumps to hold the water back, while others argue that it is wiser to move neighborhoods inland and restore marshes that naturally absorb floods. Each approach is costly, but supporters of the second note that it can also create parks and wildlife habitat.','Supporters of moving neighborhoods inland believe that this approach',NULL,'["is cheaper than pumps","could also provide parks and habitat","will stop sea levels rising","is unpopular"]',1,'Stated at the end.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-isee-reading-5b5d384a9e13','ISEE','reading','mcq',5,'In many coastal cities, rising sea levels are forcing planners to rethink where people can safely live. Some propose walls and pumps to hold the water back, while others argue that it is wiser to move neighborhoods inland and restore marshes that naturally absorb floods. Each approach is costly, but supporters of the second note that it can also create parks and wildlife habitat.','The word "restore" in the passage most nearly means',NULL,'["destroy","bring back to a former condition","measure","sell"]',1,'Restore = bring back.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-isee-reading-4a88982fbb46','ISEE','reading','mcq',2,'The first time Mara played the violin in front of an audience, her hands trembled so badly that the opening notes wobbled. She considered stopping, but the old man in the front row smiled and gave a tiny nod. Her breathing slowed. By the second page, the music seemed to play itself, and when she finally lowered her bow, the applause startled her.','Why did Mara''s breathing slow?',NULL,'["The piece became easier.","A listener gave her an encouraging nod.","She stopped playing.","The audience left."]',1,'The nod calmed her.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-isee-reading-e19ed96d863a','ISEE','reading','mcq',3,'The first time Mara played the violin in front of an audience, her hands trembled so badly that the opening notes wobbled. She considered stopping, but the old man in the front row smiled and gave a tiny nod. Her breathing slowed. By the second page, the music seemed to play itself, and when she finally lowered her bow, the applause startled her.','The word "startled" suggests that Mara felt',NULL,'["bored","surprised","embarrassed","furious"]',1,'Surprised by applause.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-isee-reading-31070f129719','ISEE','reading','mcq',4,'The first time Mara played the violin in front of an audience, her hands trembled so badly that the opening notes wobbled. She considered stopping, but the old man in the front row smiled and gave a tiny nod. Her breathing slowed. By the second page, the music seemed to play itself, and when she finally lowered her bow, the applause startled her.','Which sentence best states a theme of the passage?',NULL,'["Practice is unnecessary.","Support can help us overcome fear.","Audiences are unkind.","Violins are difficult."]',1,'Encouragement.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-isee-essay-1','ISEE','essay','text',2,NULL,'Write an essay (about 200 words) in response to: "What is the most important quality of a good friend?" Use specific examples.',NULL,NULL,NULL,NULL,1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-isee-essay-2','ISEE','essay','text',3,NULL,'Write an essay (about 200 words): "If you could change one thing about your town, what would it be and why?"',NULL,NULL,NULL,NULL,1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-map-math-73f9e1adfdb2','MAP','math','mcq',2,NULL,'A car travels at 45 miles per hour for 3 hours. How many miles does it travel?',NULL,'["15","48","135","145"]',2,'Distance = rate × time = 45 × 3.',1,0);
