INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-isee-math-031caef75f6f','ISEE','math','mcq',2,NULL,'A car travels at 45 miles per hour for 3 hours. How many miles does it travel?',NULL,'["135","48","15","145"]',0,'Distance = rate × time = 45 × 3.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-isee-math-b681c4c53df2','ISEE','math','mcq',3,NULL,'The sum of three consecutive integers is 69. What is the greatest of the three integers?',NULL,'["24","25","23","22"]',0,'The middle integer is 23, so the greatest is 24.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-isee-math-1694583f1e6c','ISEE','math','mcq',4,NULL,'What is 1/3 of 21?',NULL,'["15","7","3","10"]',1,'21 ÷ 3 × 1.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-isee-math-d3ef54b54d6d','ISEE','math','mcq',2,NULL,'The ratio of boys to girls in a class is 4:4. If there are 24 boys, how many girls are there?',NULL,'["16","10","24","28"]',2,'24 ÷ 4 = 6 groups, and 6 × 4 = 24.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-isee-math-ee67e1d591fa','ISEE','math','mcq',3,NULL,'The average of four numbers is 10. Three of the numbers are 11, 8, and 8. What is the fourth number?',NULL,'["17","11","13","10"]',2,'Total = 4 × 10 = 40; subtract 27.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-isee-math-b1f49be36142','ISEE','math','mcq',2,NULL,'A car travels at 60 miles per hour for 2.5 hours. How many miles does it travel?',NULL,'["24","62.5","150","160"]',2,'Distance = rate × time = 60 × 2.5.',1,0);
