INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-sat-math-05e2369d6f35','SAT','math','mcq',2,NULL,'If 2^x = 16, what is the value of x?',NULL,'["3","4","8","5"]',1,'2^4 = 16.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-sat-math-31dff980b6d8','SAT','math','mcq',3,NULL,'A line passes through the points (3, 5) and (4, 7). What is the slope of the line?',NULL,'["3","-2","1/2","2"]',3,'Rise over run = 2/1.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-sat-math-de2a2c5fe35a','SAT','math','mcq',2,NULL,'The mean of the five numbers 17, 10, 8, 11, 19 is 13. (Assume the mean is exactly 13.) What is the sum of the five numbers?',NULL,'["18","70","52","65"]',3,'Sum = mean × count = 13 × 5.',1,0);
