INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-cogat-verbal-05228b3173b7','COGAT','verbal','mcq',5,NULL,'Which word does NOT belong: bridge, tunnel, causeway, harbor?',NULL,'["harbor","causeway","bridge","tunnel"]',0,'The others carry travelers across or through obstacles; a harbor shelters ships.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-cogat-verbal-49788ef7d05f','COGAT','verbal','mcq',1,NULL,'The cat was so ___ that it slept all day.',NULL,'["loud","wet","tall","sleepy"]',3,'Sleeping all day fits a sleepy cat.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-cogat-verbal-abe2dedf59ec','COGAT','verbal','mcq',1,NULL,'We wore coats because the weather was ___.',NULL,'["sunny","dry","hot","cold"]',3,'People wear coats when it is cold.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-cogat-verbal-935f8c7528b3','COGAT','verbal','mcq',2,NULL,'The explorers were ___ by the sudden storm.',NULL,'["delayed","rewarded","entertained","amused"]',0,'A sudden storm would hold explorers up; the other words do not fit.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-cogat-verbal-0d26c9ddadb3','COGAT','verbal','mcq',2,NULL,'Because she practiced daily, her piano playing steadily ___.',NULL,'["stalled","declined","improved","ended"]',2,'Daily practice leads to improvement.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-cogat-verbal-0a1c86616922','COGAT','verbal','mcq',2,NULL,'The soup was so ___ that I burned my tongue.',NULL,'["thin","cold","hot","bland"]',2,'Only hot soup could burn the tongue.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-cogat-verbal-2baf8944de32','COGAT','verbal','mcq',3,NULL,'Despite the rain, the crowd remained ___, cheering loudly.',NULL,'["drowsy","enthusiastic","indifferent","gloomy"]',1,'Cheering loudly shows enthusiasm.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-cogat-verbal-868d5230ddb6','COGAT','verbal','mcq',3,NULL,'The scientist was ___ about her findings, so she checked the data twice.',NULL,'["cautious","bored","careless","boastful"]',0,'Checking twice shows caution.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-cogat-verbal-ba5a99b6052a','COGAT','verbal','mcq',3,NULL,'His ___ answer left us confused because it could mean many things.',NULL,'["ambiguous","brief","honest","precise"]',0,'An answer with many possible meanings is ambiguous.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-cogat-verbal-1cfa4f108af9','COGAT','verbal','mcq',3,NULL,'The ___ of the old bridge made engineers worry it might collapse.',NULL,'["beauty","length","fragility","history"]',2,'Fragility would make collapse a worry.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-cogat-verbal-8a4a19dcd5fb','COGAT','verbal','mcq',4,NULL,'The mayor''s speech was so ___ that many listeners began to yawn.',NULL,'["brief","witty","thrilling","tedious"]',3,'Yawning suggests the speech was boring.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-cogat-verbal-47b085606a07','COGAT','verbal','mcq',4,NULL,'Rather than ___ the problem, the team decided to face it directly.',NULL,'["avoid","discuss","examine","announce"]',0,'Facing it directly contrasts with avoiding it.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-cogat-verbal-31d7c32bf806','COGAT','verbal','mcq',4,NULL,'The desert plant is ___ to dry conditions, surviving months without rain.',NULL,'["adapted","unfamiliar","opposed","vulnerable"]',0,'Surviving months without rain shows it is adapted.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-cogat-verbal-5c13dcc0773d','COGAT','verbal','mcq',5,NULL,'Her alibi was ___ by three independent sources.',NULL,'["corroborated","ignored","fabricated","contradicted"]',0,'Independent sources confirming a story corroborate it.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-cogat-verbal-1c46e30082bd','COGAT','verbal','mcq',5,NULL,'Though the critic''s tone was ___, her review contained genuine praise.',NULL,'["generous","flattering","gentle","caustic"]',3,'"Though" signals contrast with praise, so the tone was harsh (caustic).',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-cogat-verbal-f30a28eff3fd','COGAT','verbal','mcq',5,NULL,'The senator''s ___ stance, unchanged through decades, earned him trust.',NULL,'["fickle","vague","reluctant","steadfast"]',3,'An unchanging stance is steadfast.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-wida-listening-6a483fbdd9a6','WIDA','listening','mcq',1,'Good morning, class. Today is Monday. Please put your backpack on the hook. Then sit at your table. Take out your pencil and your blue folder. We will read a story first. After the story, we will go to art.','Where should students put their backpacks?',NULL,'["In the folder","Under the chair","On the table","On the hook"]',3,'The teacher says to put the backpack on the hook.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-wida-listening-937be569bc77','WIDA','listening','mcq',1,'Good morning, class. Today is Monday. Please put your backpack on the hook. Then sit at your table. Take out your pencil and your blue folder. We will read a story first. After the story, we will go to art.','What will the class do first?',NULL,'["Draw pictures","Take a test","Read a story","Go to art"]',2,'The teacher says they will read a story first.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-wida-listening-f10ae9b55aa7','WIDA','listening','mcq',1,'My name is Ben. I have a small dog. His name is Max. Max is brown and white. He likes to run in the park. Every day after school, I take Max to the park. We play with a yellow ball.','What color is Max?',NULL,'["All brown","Yellow and white","Black and yellow","Brown and white"]',3,'Ben says Max is brown and white.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-wida-listening-b52f4d5ace18','WIDA','listening','mcq',1,'My name is Ben. I have a small dog. His name is Max. Max is brown and white. He likes to run in the park. Every day after school, I take Max to the park. We play with a yellow ball.','When does Ben take Max to the park?',NULL,'["At night","Only on Saturday","After school","Before school"]',2,'Ben says he goes every day after school.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-wida-listening-5befa4077219','WIDA','listening','mcq',2,'Ms. Lopez has eight pencils on her desk. She gives three pencils to students at the front table. Then she finds two more pencils in a drawer and puts them on her desk. Now she wants to know how many pencils are on her desk.','How many pencils are on Ms. Lopez''s desk now?',NULL,'["Ten","Seven","Five","Thirteen"]',1,'Eight minus three is five, and five plus two is seven.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-wida-listening-acdee4f8127d','WIDA','listening','mcq',2,'Ms. Lopez has eight pencils on her desk. She gives three pencils to students at the front table. Then she finds two more pencils in a drawer and puts them on her desk. Now she wants to know how many pencils are on her desk.','What did Ms. Lopez do with three of the pencils?',NULL,'["She put them in a box","She gave them to students","She lost them","She found them in a drawer"]',1,'She gave three pencils to students at the front table.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-wida-listening-fad04605c3a8','WIDA','listening','mcq',3,'Plants need three things to grow well: water, light, and air. Last week our class planted two bean seeds in cups. We put one cup near the window and the other in a dark closet. We gave both cups the same amount of water. After seven days, the bean near the window was tall and green. The bean in the closet was short and pale. This shows that plants need light to grow healthy.','Why did the class put one cup in the closet?',NULL,'["To keep it warm","To see what happens without light","To save space in the room","To give it more water"]',1,'The closet cup had no light, so it tested whether plants need light.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-wida-listening-f8a305166b55','WIDA','listening','mcq',3,'Plants need three things to grow well: water, light, and air. Last week our class planted two bean seeds in cups. We put one cup near the window and the other in a dark closet. We gave both cups the same amount of water. After seven days, the bean near the window was tall and green. The bean in the closet was short and pale. This shows that plants need light to grow healthy.','What was the same for both cups?',NULL,'["The height after seven days","The amount of water","The amount of light","The place where they sat"]',1,'The speaker says both cups got the same amount of water.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-wida-listening-6c412661dd3e','WIDA','listening','mcq',3,'Plants need three things to grow well: water, light, and air. Last week our class planted two bean seeds in cups. We put one cup near the window and the other in a dark closet. We gave both cups the same amount of water. After seven days, the bean near the window was tall and green. The bean in the closet was short and pale. This shows that plants need light to grow healthy.','What happened to the bean in the closet?',NULL,'["It was tall and green","It was given more water","It was short and pale","It grew toward the window"]',2,'The speaker says the closet bean was short and pale.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-wida-listening-12eccd3a35e2','WIDA','listening','mcq',2,'A map is a drawing of a place. Many maps have a compass rose, which shows the directions north, south, east, and west. Many maps also have a key. The key tells you what the symbols on the map mean. For example, a small picture of a tree might mean a park, and a blue line might mean a river. If you want to find a river on a map, you should look at the key first.','What does a compass rose show?',NULL,'["Parks","Distances","Directions","Rivers"]',2,'The speaker says it shows north, south, east, and west.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-wida-listening-3d7ebec33512','WIDA','listening','mcq',2,'A map is a drawing of a place. Many maps have a compass rose, which shows the directions north, south, east, and west. Many maps also have a key. The key tells you what the symbols on the map mean. For example, a small picture of a tree might mean a park, and a blue line might mean a river. If you want to find a river on a map, you should look at the key first.','Where can you learn what a symbol means?',NULL,'["On the river","In the park","In the key","In the compass rose"]',2,'The key tells what the symbols mean.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-wida-listening-ce8d0c978a4f','WIDA','listening','mcq',2,'A map is a drawing of a place. Many maps have a compass rose, which shows the directions north, south, east, and west. Many maps also have a key. The key tells you what the symbols on the map mean. For example, a small picture of a tree might mean a park, and a blue line might mean a river. If you want to find a river on a map, you should look at the key first.','What might a blue line mean on a map?',NULL,'["A tree","A park","A road","A river"]',3,'The speaker gives a blue line as an example of a river.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-wida-listening-16919d25304d','WIDA','listening','mcq',3,'Last summer, Tomas visited his grandmother in the mountains. Every morning, they walked to the river to look for smooth stones. Tomas wanted to find a perfectly round one. On the last day, he still had not found one. He felt sad. Then his grandmother smiled and handed him a stone from her pocket. She had been saving it for him since the first day.','How did Tomas feel on the last day before his grandmother gave him the stone?',NULL,'["Angry","Sleepy","Sad","Happy"]',2,'The speaker says he felt sad because he had not found a round stone.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-wida-listening-51ee02de4ad2','WIDA','listening','mcq',3,'Last summer, Tomas visited his grandmother in the mountains. Every morning, they walked to the river to look for smooth stones. Tomas wanted to find a perfectly round one. On the last day, he still had not found one. He felt sad. Then his grandmother smiled and handed him a stone from her pocket. She had been saving it for him since the first day.','What did the grandmother do?',NULL,'["She found a stone in the river","She told him to stop looking","She gave him a stone she had saved","She took his stone away"]',2,'She handed him a stone from her pocket that she had been saving.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-wida-listening-f1b392a7655b','WIDA','listening','mcq',4,'Last summer, Tomas visited his grandmother in the mountains. Every morning, they walked to the river to look for smooth stones. Tomas wanted to find a perfectly round one. On the last day, he still had not found one. He felt sad. Then his grandmother smiled and handed him a stone from her pocket. She had been saving it for him since the first day.','What can you tell about the grandmother?',NULL,'["She did not like the river","She was angry at Tomas","She wanted to make Tomas happy","She forgot about the stones"]',2,'Saving a stone for him shows she cared about his wish.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-wida-listening-e11ec3d5e98d','WIDA','listening','mcq',2,'Attention students. The school book fair starts on Tuesday and ends on Friday. It will be in the library. You can visit the fair during your lunch time or after school. Please bring money in an envelope with your name on it. Remember, the library closes at three thirty each day.','Where will the book fair be?',NULL,'["In the office","In the gym","In the library","In the cafeteria"]',2,'The announcement says it will be in the library.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-wida-listening-ed1333f173a5','WIDA','listening','mcq',2,'Attention students. The school book fair starts on Tuesday and ends on Friday. It will be in the library. You can visit the fair during your lunch time or after school. Please bring money in an envelope with your name on it. Remember, the library closes at three thirty each day.','What should students bring to the book fair?',NULL,'["A library card","A signed paper from home","Money in an envelope with their name","Their favorite book"]',2,'Students should bring money in a named envelope.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-wida-listening-b7dcd227a84f','WIDA','listening','mcq',2,'Attention students. The school book fair starts on Tuesday and ends on Friday. It will be in the library. You can visit the fair during your lunch time or after school. Please bring money in an envelope with your name on it. Remember, the library closes at three thirty each day.','On which day does the book fair end?',NULL,'["Thursday","Friday","Tuesday","Wednesday"]',1,'The speaker says the fair ends on Friday.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-wida-listening-0281c47a1f76','WIDA','listening','mcq',4,'Water on Earth moves in a cycle. The sun heats water in oceans and lakes, and some of it rises into the air as vapor. High in the sky, the cool air turns the vapor into tiny drops that form clouds. When the drops become heavy, they fall as rain or snow. Some of this water flows into rivers, which carry it back to the ocean, and the cycle begins again.','What causes water to rise into the air as vapor?',NULL,'["Cold air in the sky","Heavy clouds","Heat from the sun","Water flowing in rivers"]',2,'The sun heats the water so it rises as vapor.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-wida-listening-00495253ae3e','WIDA','listening','mcq',4,'Water on Earth moves in a cycle. The sun heats water in oceans and lakes, and some of it rises into the air as vapor. High in the sky, the cool air turns the vapor into tiny drops that form clouds. When the drops become heavy, they fall as rain or snow. Some of this water flows into rivers, which carry it back to the ocean, and the cycle begins again.','What happens when the drops in a cloud become heavy?',NULL,'["They are heated by the sun","They flow into the ocean as vapor","They turn into vapor","They fall as rain or snow"]',3,'Heavy drops fall as rain or snow.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-wida-listening-65fac6e115b9','WIDA','listening','mcq',4,'In the early 1900s, many families moved from farms to cities because factories offered jobs. Cities grew quickly, and new neighborhoods were built near the factories. However, not everyone found the move easy. Housing was crowded, and some workers earned very little money. Even so, families kept coming, hoping their children would have better opportunities than they had.','Why did many families move to cities?',NULL,'["Cities had no crowded housing","Farms had too much water","Factories offered jobs","Schools were free only in cities"]',2,'The speaker says factories offered jobs.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-wida-listening-039fa4609805','WIDA','listening','mcq',5,'In the early 1900s, many families moved from farms to cities because factories offered jobs. Cities grew quickly, and new neighborhoods were built near the factories. However, not everyone found the move easy. Housing was crowded, and some workers earned very little money. Even so, families kept coming, hoping their children would have better opportunities than they had.','What does the speaker suggest about families who kept moving to cities?',NULL,'["They hoped for a better future for their children","They earned a lot of money at first","They enjoyed the crowded housing","They were forced to leave by leaders"]',0,'The speaker says they hoped their children would have better opportunities.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-wida-listening-d6edcf0df70b','WIDA','listening','mcq',5,'The school store sells notebooks for two dollars each and pens for one dollar each. Lina has ten dollars. She buys three notebooks and wants to spend the rest on pens. Her friend says she can buy five pens, but Lina checks again. She realizes that after buying the notebooks, she only has four dollars left.','How many pens can Lina buy with the money she has left?',NULL,'["Three","Five","Six","Four"]',3,'Three notebooks cost six dollars, leaving four dollars for four pens.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-wida-listening-c088080cfcbd','WIDA','listening','mcq',5,'The school store sells notebooks for two dollars each and pens for one dollar each. Lina has ten dollars. She buys three notebooks and wants to spend the rest on pens. Her friend says she can buy five pens, but Lina checks again. She realizes that after buying the notebooks, she only has four dollars left.','Why was Lina''s friend wrong?',NULL,'["Pens cost two dollars each","The friend did not count the money spent on notebooks","Lina bought four notebooks","Lina started with only six dollars"]',1,'Five pens would need five dollars, but only four dollars were left after the notebooks.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-wida-reading-9646eb164bdc','WIDA','reading','mcq',1,'Pizza Day. Pizza day is on Friday. Lunch costs two dollars. Bring your money in an envelope. Write your name on the envelope. Give it to your teacher on Thursday.','When is pizza day?',NULL,'["On Thursday","On Monday","On Tuesday","On Friday"]',3,'The notice says pizza day is on Friday.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-wida-reading-cdb151ecd1c5','WIDA','reading','mcq',1,'Pizza Day. Pizza day is on Friday. Lunch costs two dollars. Bring your money in an envelope. Write your name on the envelope. Give it to your teacher on Thursday.','What should you write on the envelope?',NULL,'["The price","Your teacher''s name","The day","Your name"]',3,'The notice says to write your name on the envelope.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-wida-reading-2edf8422ff55','WIDA','reading','mcq',1,'Pizza Day. Pizza day is on Friday. Lunch costs two dollars. Bring your money in an envelope. Write your name on the envelope. Give it to your teacher on Thursday.','Who gets the money?',NULL,'["Your friend","The principal","The bus driver","Your teacher"]',3,'The notice says to give the envelope to your teacher.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-wida-reading-c7666ea2766b','WIDA','reading','mcq',1,'Sam has a red kite. Today the wind is strong. Sam runs to the field with his sister, Ana. The kite goes up, up, up into the sky. Then the string breaks! The kite flies away over the trees. Sam is sad, but Ana says, "We can make a new one."','What color is Sam''s kite?',NULL,'["Red","Green","Blue","Yellow"]',0,'The first sentence says Sam has a red kite.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-wida-reading-4e764f93161b','WIDA','reading','mcq',1,'Sam has a red kite. Today the wind is strong. Sam runs to the field with his sister, Ana. The kite goes up, up, up into the sky. Then the string breaks! The kite flies away over the trees. Sam is sad, but Ana says, "We can make a new one."','What happens to the kite?',NULL,'["It falls in a tree","It tears in the wind","The string breaks and it flies away","Ana takes it home"]',2,'The string breaks and the kite flies over the trees.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-wida-reading-347a049c34a4','WIDA','reading','mcq',2,'Butterflies change as they grow. First, a butterfly begins as a tiny egg on a leaf. Next, a caterpillar comes out of the egg and eats leaves for many days. Then the caterpillar makes a hard shell around itself called a chrysalis. Inside, its body changes. After about two weeks, a butterfly comes out.','What does the caterpillar eat?',NULL,'["Flowers","Leaves","Eggs","Shells"]',1,'The text says the caterpillar eats leaves.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-wida-reading-f6f5f197bff5','WIDA','reading','mcq',2,'Butterflies change as they grow. First, a butterfly begins as a tiny egg on a leaf. Next, a caterpillar comes out of the egg and eats leaves for many days. Then the caterpillar makes a hard shell around itself called a chrysalis. Inside, its body changes. After about two weeks, a butterfly comes out.','What comes right after the egg?',NULL,'["A leaf","A chrysalis","A butterfly","A caterpillar"]',3,'A caterpillar comes out of the egg.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-wida-reading-ad64dfdbc31f','WIDA','reading','mcq',2,'Butterflies change as they grow. First, a butterfly begins as a tiny egg on a leaf. Next, a caterpillar comes out of the egg and eats leaves for many days. Then the caterpillar makes a hard shell around itself called a chrysalis. Inside, its body changes. After about two weeks, a butterfly comes out.','What is the hard shell called?',NULL,'["A leaf","An egg","A chrysalis","A caterpillar"]',2,'The text names the shell a chrysalis.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-wida-reading-9f3eb5133622','WIDA','reading','mcq',3,'The Garcia family is driving to the beach. The beach is 120 miles from their home. In the first hour, they drive 50 miles. In the second hour, they drive 40 miles. Then they stop for lunch.','How many miles have they driven when they stop for lunch?',NULL,'["30 miles","90 miles","120 miles","70 miles"]',1,'50 plus 40 equals 90.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-wida-reading-9511c64d0ff6','WIDA','reading','mcq',3,'The Garcia family is driving to the beach. The beach is 120 miles from their home. In the first hour, they drive 50 miles. In the second hour, they drive 40 miles. Then they stop for lunch.','How many miles are left to drive after lunch?',NULL,'["30 miles","90 miles","70 miles","40 miles"]',0,'120 minus 90 equals 30.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-wida-reading-b010e1317517','WIDA','reading','mcq',3,'Parents and Guardians: Our class is going on a field trip to the City Science Museum on Thursday, March 12. The bus will leave school at 9:00 a.m. and return at 2:30 p.m. Students should wear comfortable shoes and bring a sack lunch. Please sign the permission slip and return it by Monday, March 9. Students without a signed slip must stay at school.','What must families do by March 9?',NULL,'["Bring a sack lunch to the museum","Send money for the bus","Return the signed permission slip","Pick up students at 2:30"]',2,'The notice asks for the signed slip by Monday, March 9.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-wida-reading-081906d123c0','WIDA','reading','mcq',3,'Parents and Guardians: Our class is going on a field trip to the City Science Museum on Thursday, March 12. The bus will leave school at 9:00 a.m. and return at 2:30 p.m. Students should wear comfortable shoes and bring a sack lunch. Please sign the permission slip and return it by Monday, March 9. Students without a signed slip must stay at school.','What should students bring on the trip?',NULL,'["Museum tickets","A science book","A sack lunch","A permission slip only"]',2,'Students should wear comfortable shoes and bring a sack lunch.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-wida-reading-1ce1f87f36a1','WIDA','reading','mcq',3,'Parents and Guardians: Our class is going on a field trip to the City Science Museum on Thursday, March 12. The bus will leave school at 9:00 a.m. and return at 2:30 p.m. Students should wear comfortable shoes and bring a sack lunch. Please sign the permission slip and return it by Monday, March 9. Students without a signed slip must stay at school.','What happens to a student without a signed slip?',NULL,'["The student stays at school","The student goes with another class","The student pays at the museum","The student rides the bus later"]',0,'The notice says those students must stay at school.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-wida-reading-d8ad7ab4976b','WIDA','reading','mcq',3,'Priya had practiced her speech for a week, but when she stood in front of the class, her mind went blank. Her hands shook, and the words disappeared. She looked at her teacher, who nodded gently. Priya took a deep breath, looked at her notes, and began again slowly. By the end, her classmates were clapping.','How did Priya most likely feel in front of the class?',NULL,'["Sleepy","Proud","Nervous","Bored"]',2,'Her shaking hands and forgotten words show she was nervous.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-wida-reading-76ccc3e57b0b','WIDA','reading','mcq',4,'Priya had practiced her speech for a week, but when she stood in front of the class, her mind went blank. Her hands shook, and the words disappeared. She looked at her teacher, who nodded gently. Priya took a deep breath, looked at her notes, and began again slowly. By the end, her classmates were clapping.','What does "her mind went blank" mean?',NULL,'["She fell asleep","She lost her notes","She could not remember what to say","She was thinking of something fun"]',2,'The words disappeared from her memory.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-wida-reading-a9008061a464','WIDA','reading','mcq',3,'Priya had practiced her speech for a week, but when she stood in front of the class, her mind went blank. Her hands shook, and the words disappeared. She looked at her teacher, who nodded gently. Priya took a deep breath, looked at her notes, and began again slowly. By the end, her classmates were clapping.','What helped Priya finish her speech?',NULL,'["A deep breath, her notes, and her teacher''s nod","A new teacher","Help from her classmates","A longer speech"]',0,'She calmed down, used her notes, and had her teacher''s support.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-wida-reading-6849c682e56c','WIDA','reading','mcq',4,'A community needs rules and laws to keep people safe and to help them live together fairly. For example, traffic laws tell drivers when to stop and go, which prevents accidents. Leaders, such as a mayor, help make decisions for the community. Citizens also have responsibilities. They should follow the rules, vote when they are old enough, and help their neighbors.','Why do communities have traffic laws?',NULL,'["To make neighbors friends","To make driving faster","To prevent accidents","To help mayors win"]',2,'The text says traffic laws prevent accidents.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-wida-reading-c0a9826b126b','WIDA','reading','mcq',4,'A community needs rules and laws to keep people safe and to help them live together fairly. For example, traffic laws tell drivers when to stop and go, which prevents accidents. Leaders, such as a mayor, help make decisions for the community. Citizens also have responsibilities. They should follow the rules, vote when they are old enough, and help their neighbors.','Which is a responsibility of citizens?',NULL,'["Writing all traffic laws","Paying other drivers","Becoming the mayor","Voting when they are old enough"]',3,'The text lists voting when old enough as a responsibility.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-wida-reading-7817774e8ebf','WIDA','reading','mcq',4,'Sound is made when objects vibrate, or move back and forth very quickly. These vibrations travel through the air as waves until they reach our ears. If you touch your throat while you talk, you can feel the vibrations. Sound cannot travel in space because there is no air there to carry the vibrations. That is why astronauts use radios to talk to one another outside their spaceships.','What makes sound?',NULL,'["Vibrations","Light","Silence","Space"]',0,'Sound is made when objects vibrate.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-wida-reading-9045bb064c0a','WIDA','reading','mcq',5,'Sound is made when objects vibrate, or move back and forth very quickly. These vibrations travel through the air as waves until they reach our ears. If you touch your throat while you talk, you can feel the vibrations. Sound cannot travel in space because there is no air there to carry the vibrations. That is why astronauts use radios to talk to one another outside their spaceships.','Why do astronauts use radios outside their spaceships?',NULL,'["Radios are louder than voices","Space is too bright","Astronauts cannot feel vibrations","There is no air in space to carry sound"]',3,'Sound needs air to travel, and space has none.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-wida-reading-3d179da1ff04','WIDA','reading','mcq',5,'When the town council announced plans to cut down the old oak tree in Maple Park, many residents were upset. The tree was more than one hundred years old, and generations of children had climbed its branches. However, an engineer explained that its roots were damaging the water pipes beneath the park. After several meetings, the council decided to move the pipes instead, so the tree could stay.','Why did the council first plan to cut down the tree?',NULL,'["It was too old to climb","Its roots were damaging water pipes","Children had hurt it","It blocked the park entrance"]',1,'The engineer explained the roots were damaging the pipes.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-wida-reading-8554756fe5f1','WIDA','reading','mcq',5,'When the town council announced plans to cut down the old oak tree in Maple Park, many residents were upset. The tree was more than one hundred years old, and generations of children had climbed its branches. However, an engineer explained that its roots were damaging the water pipes beneath the park. After several meetings, the council decided to move the pipes instead, so the tree could stay.','What can you conclude about the council?',NULL,'["It ignored the engineer''s advice","It changed its plan after hearing the community''s concerns","It did not care about the park","It wanted to build a new park"]',1,'The council first planned to cut the tree, then moved the pipes after meetings.',1,0);
